package org.eclipse.kura.internal.rest.auth.jwt;

import static org.junit.Assert.assertThrows;

import org.eclipse.kura.KuraErrorCode;
import org.eclipse.kura.KuraException;
import org.junit.Test;

import jakarta.ws.rs.WebApplicationException;
import jakarta.ws.rs.core.Response.Status;

public class RefreshTokenFamilyIssuingFailureTest extends AbstractRefreshTokenFamilyScenario {

    private static final int UNAUTHORIZED = Status.UNAUTHORIZED.getStatusCode();

    @Test
    public void aFailedIssuingLeavesNoFamilyToRefresh() {
        givenIssuingRefreshTokensFailsWith(new KuraException(KuraErrorCode.SECURITY_EXCEPTION));
        givenTheLoginFailedWith(WebApplicationException.class);
        givenIssuingWorksAgain();

        whenARefreshTokenOfTheRefusedFamilyIsExchanged();

        thenTheExchangeStatusesAre(UNAUTHORIZED);
    }

    @Test
    public void anUnexpectedIssuingErrorLeavesNoFamilyToRefresh() {
        givenIssuingRefreshTokensFailsWith(new IllegalStateException());
        givenTheLoginFailedWith(IllegalStateException.class);
        givenIssuingWorksAgain();

        whenARefreshTokenOfTheRefusedFamilyIsExchanged();

        thenTheExchangeStatusesAre(UNAUTHORIZED);
    }

    private void givenIssuingRefreshTokensFailsWith(final Exception failure) {
        failIssuingRefreshTokensWith(failure);
    }

    private void givenTheLoginFailedWith(final Class<? extends Exception> failure) {
        assertThrows(failure, this::login);
    }

    private void givenIssuingWorksAgain() {
        stopFailingIssuing();
    }

    private void whenARefreshTokenOfTheRefusedFamilyIsExchanged() {
        exchange(externalRefreshTokenWith(IDENTITY, refusedRefreshTokenClaims()));
    }
}
